"use strict";
import { Interface } from "@ethersproject/abi";
const MAX_UINT256 = BigInt("0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff");
const ERC20_INTERFACE = new Interface([
  {
    inputs: [
      { internalType: "address", name: "spender", type: "address" },
      { internalType: "uint256", name: "amount", type: "uint256" }
    ],
    name: "approve",
    outputs: [{ internalType: "bool", name: "", type: "bool" }],
    stateMutability: "nonpayable",
    type: "function"
  }
]);
const VAULT_INTERFACE = new Interface([
  {
    inputs: [
      { name: "assets", type: "uint256" },
      { name: "receiver", type: "address" }
    ],
    name: "deposit",
    outputs: [{ name: "shares", type: "uint256" }],
    stateMutability: "nonpayable",
    type: "function"
  },
  {
    inputs: [
      { name: "shares", type: "uint256" },
      { name: "receiver", type: "address" },
      { name: "owner", type: "address" }
    ],
    name: "redeem",
    outputs: [{ name: "assets", type: "uint256" }],
    stateMutability: "nonpayable",
    type: "function"
  }
]);
const MORPHO_INTERFACE = new Interface([
  {
    inputs: [
      {
        components: [
          { name: "loanToken", type: "address" },
          { name: "collateralToken", type: "address" },
          { name: "oracle", type: "address" },
          { name: "irm", type: "address" },
          { name: "lltv", type: "uint256" }
        ],
        name: "marketParams",
        type: "tuple"
      },
      { name: "assets", type: "uint256" },
      { name: "onBehalf", type: "address" },
      { name: "data", type: "bytes" }
    ],
    name: "supplyCollateral",
    outputs: [],
    stateMutability: "nonpayable",
    type: "function"
  },
  {
    inputs: [
      {
        components: [
          { name: "loanToken", type: "address" },
          { name: "collateralToken", type: "address" },
          { name: "oracle", type: "address" },
          { name: "irm", type: "address" },
          { name: "lltv", type: "uint256" }
        ],
        name: "marketParams",
        type: "tuple"
      },
      { name: "assets", type: "uint256" },
      { name: "shares", type: "uint256" },
      { name: "onBehalf", type: "address" },
      { name: "receiver", type: "address" }
    ],
    name: "borrow",
    outputs: [
      { name: "assetsBorrowed", type: "uint256" },
      { name: "sharesBorrowed", type: "uint256" }
    ],
    stateMutability: "nonpayable",
    type: "function"
  },
  {
    inputs: [
      {
        components: [
          { name: "loanToken", type: "address" },
          { name: "collateralToken", type: "address" },
          { name: "oracle", type: "address" },
          { name: "irm", type: "address" },
          { name: "lltv", type: "uint256" }
        ],
        name: "marketParams",
        type: "tuple"
      },
      { name: "assets", type: "uint256" },
      { name: "shares", type: "uint256" },
      { name: "onBehalf", type: "address" },
      { name: "data", type: "bytes" }
    ],
    name: "repay",
    outputs: [
      { name: "assetsRepaid", type: "uint256" },
      { name: "sharesRepaid", type: "uint256" }
    ],
    stateMutability: "nonpayable",
    type: "function"
  }
]);
export class MorphoBatchedTransactionService {
  buildBatchedVaultDeposit(params) {
    const { assetAddress, vaultAddress, amount, account, chainId } = params;
    const approvalTx = {
      to: assetAddress,
      from: account,
      data: ERC20_INTERFACE.encodeFunctionData("approve", [vaultAddress, MAX_UINT256]),
      value: "0x0",
      chainId,
      type: 2
    };
    const depositTx = {
      to: vaultAddress,
      from: account,
      data: VAULT_INTERFACE.encodeFunctionData("deposit", [amount, account]),
      value: "0x0",
      chainId,
      type: 2
    };
    return [approvalTx, depositTx];
  }
  buildBatchedSupplyCollateralAndBorrow(params) {
    const { collateralTokenAddress, morphoAddress, marketParams, collateralAmount, borrowAmount, account, chainId } = params;
    const marketParamsArray = [
      marketParams.loanToken,
      marketParams.collateralToken,
      marketParams.oracle,
      marketParams.irm,
      marketParams.lltv
    ];
    const txs = [];
    txs.push({
      to: collateralTokenAddress,
      from: account,
      data: ERC20_INTERFACE.encodeFunctionData("approve", [morphoAddress, MAX_UINT256]),
      value: "0x0",
      chainId,
      type: 2
    });
    txs.push({
      to: morphoAddress,
      from: account,
      data: MORPHO_INTERFACE.encodeFunctionData("supplyCollateral", [marketParamsArray, collateralAmount, account, "0x"]),
      value: "0x0",
      chainId,
      type: 2
    });
    if (borrowAmount > 0n) {
      txs.push({
        to: morphoAddress,
        from: account,
        data: MORPHO_INTERFACE.encodeFunctionData("borrow", [marketParamsArray, borrowAmount, 0n, account, account]),
        value: "0x0",
        chainId,
        type: 2
      });
    }
    return txs;
  }
  buildBatchedRepay(params) {
    const { loanTokenAddress, morphoAddress, marketParams, repayAmount, account, chainId } = params;
    const marketParamsArray = [
      marketParams.loanToken,
      marketParams.collateralToken,
      marketParams.oracle,
      marketParams.irm,
      marketParams.lltv
    ];
    const approvalTx = {
      to: loanTokenAddress,
      from: account,
      data: ERC20_INTERFACE.encodeFunctionData("approve", [morphoAddress, MAX_UINT256]),
      value: "0x0",
      chainId,
      type: 2
    };
    const repayTx = {
      to: morphoAddress,
      from: account,
      data: MORPHO_INTERFACE.encodeFunctionData("repay", [marketParamsArray, repayAmount, 0n, account, "0x"]),
      value: "0x0",
      chainId,
      type: 2
    };
    return [approvalTx, repayTx];
  }
  buildVaultWithdraw(params) {
    const { vaultAddress, shares, account, chainId } = params;
    const redeemTx = {
      to: vaultAddress,
      from: account,
      data: VAULT_INTERFACE.encodeFunctionData("redeem", [shares, account, account]),
      value: "0x0",
      chainId,
      type: 2
    };
    return [redeemTx];
  }
  buildBatchedAddCollateral(params) {
    const { collateralTokenAddress, morphoAddress, marketParams, collateralAmount, account, chainId } = params;
    const marketParamsArray = [
      marketParams.loanToken,
      marketParams.collateralToken,
      marketParams.oracle,
      marketParams.irm,
      marketParams.lltv
    ];
    const approvalTx = {
      to: collateralTokenAddress,
      from: account,
      data: ERC20_INTERFACE.encodeFunctionData("approve", [morphoAddress, MAX_UINT256]),
      value: "0x0",
      chainId,
      type: 2
    };
    const supplyTx = {
      to: morphoAddress,
      from: account,
      data: MORPHO_INTERFACE.encodeFunctionData("supplyCollateral", [marketParamsArray, collateralAmount, account, "0x"]),
      value: "0x0",
      chainId,
      type: 2
    };
    return [approvalTx, supplyTx];
  }
}
