const MARKETS_QUERY = `
  query GetMorphoMarkets($first: Int!, $skip: Int!) {
    markets(
      first: $first
      skip: $skip
      orderBy: totalValueLockedUSD
      orderDirection: desc
      where: { isActive: true }
    ) {
      id
      name
      isActive
      canBorrowFrom
      canUseAsCollateral
      maximumLTV
      liquidationThreshold
      liquidationPenalty
      inputToken {
        id
        symbol
        name
        decimals
      }
      inputTokenBalance
      inputTokenPriceUSD
      borrowedToken {
        id
        symbol
        name
        decimals
      }
      variableBorrowedTokenBalance
      rates {
        id
        rate
        side
        type
      }
      totalValueLockedUSD
      totalDepositBalanceUSD
      totalBorrowBalanceUSD
      cumulativeDepositUSD
      cumulativeBorrowUSD
      cumulativeLiquidateUSD
      transactionCount
      depositCount
      withdrawCount
      borrowCount
      repayCount
      liquidationCount
      positionCount
      openPositionCount
      lltv
      totalSupply
      totalBorrow
      totalCollateral
      fee
      lastUpdate
    }
  }
`

