export function getBorrowRateFromRates(rates: MorphoInterestRate[]): number {
  const borrowRate = rates.find((r) => r.side === 'BORROWER')
  if (!borrowRate) return 0
  return parseFloat(borrowRate.rate) * 100
}

export function getSupplyRateFromRates(rates: MorphoInterestRate[]): number {
  const supplyRate = rates.find((r) => r.side === 'LENDER')
  if (!supplyRate) return 0
  return parseFloat(supplyRate.rate) * 100
}

export function formatTokenAmount(amount: string, decimals: number): string {
  const value = parseFloat(amount) / Math.pow(10, decimals)
  return value.toLocaleString(undefined, { maximumFractionDigits: 4 })
}

